<main class="wrap">
  <p class="eyebrow">Napi nyomon követés</p>
  <h1>Szokáskövető</h1>
  <p class="lead">Kattints egy napra, hogy jelöld a teljesítést. A sorozat azt mutatja, hány egymást követő nap ment egyben.</p>

  <section class="summary" aria-label="Összefoglalás">
    <div>
      <div class="stat-num" id="bestStreak">0</div>
      <div class="stat-label">Leghosszabb sorozat (nap)</div>
    </div>
    <div class="ring-wrap">
      <div class="ring">
        <svg viewBox="0 0 96 96" aria-hidden="true">
          <circle class="ring-track" cx="48" cy="48" r="40"></circle>
          <circle class="ring-prog" id="ringProg" cx="48" cy="48" r="40" transform="rotate(-90 48 48)"></circle>
        </svg>
        <div class="ring-center"><b id="ringText">0%</b></div>
      </div>
      <div class="stat-label">Mai teljesítés</div>
    </div>
  </section>

  <div id="list"></div>

  <form class="add-form" id="addForm" aria-label="Új szokás hozzáadása">
    <label class="sr-only" for="newHabit" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)">Új szokás neve</label>
    <input id="newHabit" type="text" placeholder="Új szokás neve…" autocomplete="off" maxlength="40">
    <button type="submit">Hozzáad</button>
  </form>
  <p class="hint">Például: „Edzés”, „Olvasás 20 percet”, „Vízivétel”.</p>

  <div class="live" id="live" aria-live="polite"></div>
