<script>
(function () {
  const KEY = 'habit-tracker-v1';
  const DAY_LABELS = ['H', 'K', 'Sze', 'Cs', 'P', 'Szo', 'V'];
  const DAY_FULL = ['hétfő', 'kedd', 'szerda', 'csütörtök', 'péntek', 'szombat', 'vasárnap'];
  const CIRC = 2 * Math.PI * 40;

  const listEl = document.getElementById('list');
  const addForm = document.getElementById('addForm');
  const input = document.getElementById('newHabit');
  const live = document.getElementById('live');
  const bestEl = document.getElementById('bestStreak');
  const ringProg = document.getElementById('ringProg');
  const ringText = document.getElementById('ringText');

  let habits = [];
  let store = (window.alfy && window.alfy.storage) ? window.alfy.storage : null;

  function isoDate(d) {
    return d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0');
  }
  function currentMonday() {
    const t = new Date();
    const off = (t.getDay() + 6) % 7;
    const m = new Date(t.getFullYear(), t.getMonth(), t.getDate() - off);
    return m.getTime();
  }
  function weekDates() {
    const base = currentMonday();
    const out = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(base);
      d.setDate(d.getDate() + i);
      out.push({ iso: isoDate(d), day: d.getDate(), dow: i });
    }
    return out;
  }
  function isDone(h, iso) {
    for (let i = 0; i < h.completed.length; i++) if (h.completed[i] === iso) return true;
    return false;
  }
  function toggle(h, iso) {
    const i = h.completed.indexOf(iso);
    if (i >= 0) h.completed.splice(i, 1); else h.completed.push(iso);
  }
  function computeStreak(h) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    let s = 0, cur = new Date(today);
    if (!isDone(h, isoDate(cur))) cur.setDate(cur.getDate() - 1);
    while (isDone(h, isoDate(cur))) { s++; cur.setDate(cur.getDate() - 1); }
    return s;
  }

  function announce(msg) { live.textContent = ''; setTimeout(() => { live.textContent = msg; }, 30); }

  function save() { if (store) store.set(KEY, { habits: habits }); }

  async function load() {
    if (store) {
      try {
        const s = await store.get(KEY);
        if (s && Array.isArray(s.habits)) {
          habits = s.habits.map(h => ({
            id: h.id || ('h' + Math.random().toString(36).slice(2)),
            name: String(h.name || ''),
            completed: Array.isArray(h.completed) ? h.completed : []
          }));
        }
      } catch (e) { habits = []; }
    }
    if (habits.length === 0) {
      habits = [
        { id: 'h1', name: 'Edzés', completed: [] },
        { id: 'h2', name: 'Olvasás 20 percet', completed: [] },
        { id: 'h3', name: 'Vízivétel', completed: [] },
        { id: 'h4', name: 'Meditáció', completed: [] },
        { id: 'h5', name: 'Korán lefekvés', completed: [] }
      ];
    }
    render();
  }

  function render() {
    const dates = weekDates();
    const todayIso = isoDate(new Date());

    if (habits.length === 0) {
      listEl.innerHTML = '<div class="empty"><p>Még nincs szokásod. Add hozzá az elsőt, és kezdd el a jelölést!</p></div>';
    } else {
      listEl.innerHTML = '';
      habits.forEach(h => {
        const card = document.createElement('section');
        card.className = 'card';

        const head = document.createElement('div');
        head.className = 'card-head';
        const name = document.createElement('span');
        name.className = 'card-name';
        name.textContent = h.name;
        const streak = computeStreak(h);
        const badge = document.createElement('span');
        badge.className = 'streak' + (streak === 0 ? ' zero' : '');
        badge.textContent = streak > 0 ? streak + ' napos sorozat' : 'Nincs sorozat';
        head.appendChild(name);
        head.appendChild(badge);

        const del = document.createElement('button');
        del.type = 'button';
        del.className = 'delete';
        del.textContent = '×';
        del.setAttribute('aria-label', '„' + h.name + '” törlése');
        del.addEventListener('click', () => removeHabit(h.id));
        head.appendChild(del);

        const days = document.createElement('div');
        days.className = 'days';
        dates.forEach(d => {
          const done = isDone(h, d.iso);
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'day' + (done ? ' done' : '') + (d.iso === todayIso ? ' today' : '');
          b.setAttribute('aria-pressed', done ? 'true' : 'false');
          b.setAttribute('aria-label', h.name + ' — ' + DAY_FULL[d.dow] + (d.iso === todayIso ? ' (ma)' : '') + (done ? ', teljesítve' : ', nem teljesítve'));
          b.innerHTML = '<span class="dl">' + DAY_LABELS[d.dow] + '</span><span class="dn">' + d.day + '</span>';
          b.addEventListener('click', () => {
            toggle(h, d.iso);
            save();
            announce(h.name + ': ' + DAY_FULL[d.dow] + (isDone(h, d.iso) ? ' teljesítve.' : ' jelölés törölve.'));
            render();
          });
          days.appendChild(b);
        });

        card.appendChild(head);
        card.appendChild(days);
        listEl.appendChild(card);
      });
    }

    let best = 0, doneToday = 0;
    habits.forEach(h => {
      const s = computeStreak(h);
      if (s > best) best = s;
      if (isDone(h, todayIso)) doneToday++;
    });
    bestEl.textContent = best;
    const pct = habits.length ? Math.round(doneToday / habits.length * 100) : 0;
    ringProg.style.strokeDasharray = CIRC + ' ' + CIRC;
    ringProg.style.strokeDashoffset = CIRC * (1 - pct / 100);
    ringText.textContent = pct + '%';
  }

  function removeHabit(id) {
    habits = habits.filter(h => h.id !== id);
    save();
    announce('Szokás törölve.');
    render();
  }

  addForm.addEventListener('submit', e => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) { announce('Írd be a szokás nevét.'); return; }
    habits.push({ id: 'h' + Math.random().toString(36).slice(2), name: name, completed: [] });
    input.value = '';
    save();
    announce('„' + name + '” hozzáadva.');
    render();
    input.focus();
  });

  load();
})();
</script>
</body>
